// Prepara el catálogo de categorías/documentos y el caso para el agente
const inp = $('Validar Entrada1').first().json;
const reglas = $('Leer Reglas Activas1').all().map((i) => i.json).filter((j) => j && !j.error && Object.keys(j).length);

const nombre = (d) => (typeof d === 'string' ? d : (d && (d.name || d.nombre || d.title)) || '');
const docsDe = (r) => {
  let v = r.required_documents ?? r.requiredDocuments ?? r.documents_required ?? [];
  if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { v = v.split(/[;\n]+/); } }
  if (!Array.isArray(v)) v = [];
  return v.map(nombre).map((s) => String(s).trim()).filter(Boolean);
};
const subsDe = (r) => {
  let v = r.subcategories ?? [];
  if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { v = []; } }
  return Array.isArray(v) ? v.map(nombre).map((s) => String(s).trim()).filter(Boolean) : [];
};

const catalogo = reglas
  .map((r) => ({
    category: String(r.category || r.slug || '').trim(),
    label: r.label || r.title || r.name || '',
    subcategories: subsDe(r).slice(0, 12),
    documents: docsDe(r).slice(0, 12)
  }))
  .filter((c) => c.category);

const caso = {
  caseKind: inp.caseKind,
  summary: inp.summary,
  otherParty: inp.otherParty,
  occurredAt: inp.occurredAt,
  amountChoice: inp.amountChoice,
  amount: inp.amount
};

return [{ json: { catalogo, catalogoJson: JSON.stringify(catalogo), casoJson: JSON.stringify(caso) } }];

// Valida y normaliza lo que llega de la web
const hook = $('Webhook POST /ptd-docs-requeridos1').first().json;
const b = hook.body || {};
const err = (m) => [{ json: { ok: false, error: m } }];

const summary = String(b.summary || '').trim();
const otherParty = String(b.otherParty || '').trim();
const caseKind = String(b.caseKind || 'auto').trim().toLowerCase().slice(0, 60);
const occurredAt = String(b.occurredAt || 'unknown').trim();
const amountChoice = String(b.amountChoice || '').trim();
const amount = (b.amount === null || b.amount === undefined || b.amount === '') ? null : Number(b.amount);

if (summary.length < 10 || summary.length > 1200) return err('summary invalido');
if (otherParty.length < 2 || otherParty.length > 120) return err('otherParty invalido');
if (!['approx', 'calculate', 'no_amount'].includes(amountChoice)) return err('amountChoice invalido');
if (amountChoice === 'approx' && !(amount > 0)) return err('amount invalido');
if (occurredAt !== 'unknown' && !/^\d{4}-\d{2}-\d{2}$/.test(occurredAt)) return err('occurredAt invalido');

return [{ json: { ok: true, precheckId: String(b.precheckId || ''), caseKind, summary, otherParty, occurredAt, amountChoice, amount } }];

// Valida la salida del agente; si falla, usa un respaldo determinista
const inp = $('Validar Entrada1').first().json;
const catalogo = $('Preparar Contexto').first().json.catalogo || [];
const slugs = catalogo.map((c) => c.category);

const raw = $json.output || $json.text || '';
const m = typeof raw === 'string' ? raw.match(/\{[\s\S]*\}/) : null;
let out = null;
try { out = m ? JSON.parse(m[0]) : (raw && typeof raw === 'object' ? raw : null); } catch (e) { out = null; }

const limpiar = (s, max) => String(s || '').replace(/https?:\/\/\S+/gi, '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, max);

const GENERICOS = [
  { name: 'Justificante de pago, factura o contrato', description: 'Para acreditar qué contrataste o compraste y cuánto pagaste.' },
  { name: 'Comunicaciones con la empresa', description: 'Correos, mensajes o reclamaciones previas que muestren lo ocurrido y su respuesta.' }
];

let category = 'sin_clasificar';
let subcategory = '';
let confidence = 0;
let docs = [];

if (out && typeof out === 'object') {
  category = String(out.category || 'sin_clasificar');
  if (category !== 'sin_clasificar' && !slugs.includes(category)) category = 'sin_clasificar';
  subcategory = limpiar(out.subcategory, 80);
  confidence = Math.max(0, Math.min(100, Math.round(Number(out.confidence) || 0)));
  const vistos = new Set();
  for (const d of (Array.isArray(out.documents) ? out.documents : [])) {
    const name = limpiar(d && d.name, 90);
    const desc = limpiar(d && d.description, 140);
    if (!name || vistos.has(name.toLowerCase())) continue;
    vistos.add(name.toLowerCase());
    docs.push({ name, description: desc || 'Necesario para estudiar tu caso.' });
    if (docs.length === 5) break;
  }
}

if (!docs.length) {
  // Respaldo: documentos de la categoría declarada o lista genérica
  const declarada = catalogo.find((c) => c.category === inp.caseKind);
  category = declarada ? declarada.category : 'sin_clasificar';
  subcategory = '';
  confidence = declarada ? 60 : 0;
  docs = (declarada && declarada.documents.length)
    ? declarada.documents.slice(0, 4).map((n) => ({ name: limpiar(n, 90), description: 'Necesario para estudiar tu caso.' }))
    : GENERICOS;
}

const requiredDocuments = docs.map((d, i) => ({ id: 'd' + (i + 1), name: d.name, description: d.description }));

return [{
  json: {
    success: true,
    category,
    subcategory,
    confidence,
    requiredDocuments,
    minimumDocuments: requiredDocuments.length
  }
}];
